import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import Ajv from 'ajv';
import type {ErrorObject, ValidateFunction} from 'ajv';
import {log} from '../../shared/logger.js';

const validator = new Ajv({strict: false, validateFormats: false} as unknown as ConstructorParameters<typeof Ajv>[0]);

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  staticValidator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly dynamicValidators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private getDynamicValidator(schema: object): ValidateFunction {
    const cached = this.dynamicValidators.get(schema);
    if (cached) return cached;
    const validate = validator.compile(schema);
    this.dynamicValidators.set(schema, validate);
    return validate;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const stored: StoredTool = {definitionSource: definition, execute};
    if (typeof definition !== 'function') {
      try {
        stored.staticValidator = validator.compile(resolved.inputSchema);
      } catch (error) {
        throw new Error(`Invalid inputSchema for tool ${resolved.name}: ${String(error)}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, stored);
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Returns schema rejections as ToolResponses; only unknown tool names throw (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    let validate = tool.staticValidator;
    if (!validate) {
      validate = this.getDynamicValidator(definition.inputSchema);
    }
    if (!validate(input)) {
      const error = validate.errors?.[0] as (ErrorObject & {instancePath?: string; dataPath?: string}) | undefined;
      const params = error?.params as Record<string, unknown> | undefined;
      const instancePath = error?.instancePath ?? error?.dataPath ?? '';
      const path =
        `${instancePath}${error?.keyword === 'required' ? `/${String(params?.missingProperty ?? '')}` : ''}` || '/';
      const constraint =
        error?.keyword === 'required'
          ? 'is required'
          : error?.keyword === 'type'
            ? `must be ${String(params?.type ?? 'valid')}`
            : error?.keyword === 'enum'
              ? `must match one of enum values: ${Array.isArray(params?.allowedValues) ? formatAllowedValues(params.allowedValues) : 'the declared values'}`
              : `failed ${String(error?.keyword ?? 'schema')} validation`;
      return {result: `${path} ${constraint}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

function formatAllowedValues(values: unknown[]): string {
  return values.map(String).join(', ');
}
import {jest} from '@jest/globals';
import Ajv from 'ajv';
import {ToolRegistry} from './registry.js';

const registerWeatherTool = (registry: ToolRegistry, execute: (input: Record<string, unknown>) => Promise<string>) => {
  registry.register(
    {
      name: 'get_weather',
      description: 'Get weather for a location',
      inputSchema: {
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      },
    },
    execute
  );
};

describe('ToolRegistry input validation', () => {
  it('compiles a static tool schema once across repeated executions', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    registry.register(
      {name: 'get_weather', description: 'Get weather', inputSchema: {type: 'object'}},
      async () => 'sunny'
    );

    for (let call = 0; call < 10; call++) await registry.execute('get_weather', {});

    expect(compile).toHaveBeenCalledTimes(1);
    compile.mockRestore();
  });

  it('validates each function-valued tool definition against its current schema', async () => {
    const registry = new ToolRegistry();
    let definitionCalls = 0;
    registry.register(
      () => {
        definitionCalls += 1;
        const property = definitionCalls <= 2 ? 'first' : 'second';
        return {
          name: 'dynamic_tool',
          description: 'A dynamic tool',
          inputSchema: {
            type: 'object',
            properties: {[property]: {type: 'string'}},
            required: [property],
          },
        };
      },
      async () => 'ok'
    );

    const first = await registry.execute('dynamic_tool', {first: 'one'});
    const second = await registry.execute('dynamic_tool', {second: 'two'});

    expect([first.result, second.result]).toEqual(['ok', 'ok']);
  });

  it('passes valid input with extra properties unchanged to the executor', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Berlin', unit: 'celsius'};
    const executor = jest.fn(async (received: Record<string, unknown>) => JSON.stringify(received));
    registerWeatherTool(registry, executor);

    await registry.execute('get_weather', input);

    expect(executor.mock.calls).toEqual([[input]]);
  });

  it('rejects a value outside the declared enum', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'sunny');
    let executorCalls = 0;
    executor.mockImplementation(async () => {
      executorCalls += 1;
      return 'sunny';
    });
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather',
        inputSchema: {type: 'object', properties: {unit: {type: 'string', enum: ['celsius', 'fahrenheit']}}},
      },
      executor
    );

    const response = await registry.execute('get_weather', {unit: 'kelvin'});

    expect({result: response.result, calls: executorCalls}).toMatchObject({
      result: expect.stringMatching(/\/unit.*enum.*celsius.*fahrenheit/i),
      calls: 0,
    });
  });

  it('throws for an unregistered tool name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing_tool', {})).rejects.toThrow('Unknown tool: missing_tool');
  });

  it('includes the field path and expected type in a type rejection', async () => {
    const registry = new ToolRegistry();
    registerWeatherTool(registry, async () => 'sunny');

    const response = await registry.execute('get_weather', {location: 123});

    expect(response.result).toMatch(/\/location.*string/i);
  });

  it('formats nested validation paths as JSON pointers', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'profile_tool',
        description: 'Validate a profile',
        inputSchema: {
          type: 'object',
          properties: {profile: {type: 'object', properties: {location: {type: 'string'}}}},
        },
      },
      async () => 'ok'
    );

    const response = await registry.execute('profile_tool', {profile: {location: 123}});

    expect(response.result).toMatch(/^\/profile\/location must be string$/);
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46), [includes the field path and expected type in a type rejection](../../src/orchestration/tools/registry.test.ts#L103)).
- A nested validation failure reports its path as a JSON pointer ([validated by: formats nested validation paths as JSON pointers](../../src/orchestration/tools/registry.test.ts#L112)).
- When `input` satisfies the declared constraints, `ToolRegistry.execute` passes the original input object to the executor unchanged, including undeclared extra properties ([validated by: passes valid input with extra properties unchanged to the executor](../../src/orchestration/tools/registry.test.ts#L61)).
- When a property violates its declared `enum`, the rejection result names the property and enum constraint without invoking the executor ([validated by: rejects a value outside the declared enum](../../src/orchestration/tools/registry.test.ts#L72)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults.
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake ([validated by: throws for an unregistered tool name](../../src/orchestration/tools/registry.test.ts#L97)).

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema`.
- A static tool's schema validator is compiled once at registration and reused across repeated executions ([validated by: compiles a static tool schema once across repeated executions](../../src/orchestration/tools/registry.test.ts#L21)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules.
- A function-valued tool definition validates each call against the schema returned for that call ([validated by: validates each function-valued tool definition against its current schema](../../src/orchestration/tools/registry.test.ts#L35)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
